import numpy as np
shape={(0,0),(0,1),(1,2)}
def transforms(S):
 out=[]
 for refl in [False,True]:
  for k in range(4):
   coords=[]
   for r,c in S:
    if refl: c=-c
    for _ in range(k): r,c=c,-r
    coords.append((r,c))
   mr=min(r for r,c in coords); mc=min(c for r,c in coords)
   norm=frozenset((r-mr,c-mc) for r,c in coords)
   if norm not in out: out.append(norm)
 return out
shapes=transforms(shape); len(shapes),shapes

def cover_match(mat, shapelist):
 h,w=len(mat),len(mat[0]); cover=set(); matches=[]
 for s in shapelist:
  H=max(r for r,c in s)+1; W=max(c for r,c in s)+1
  for r in range(h-H+1):
   for c in range(w-W+1):
    cells={(r+dr,c+dc) for dr,dc in s}
    if all(mat[i][j]==0 for i,j in cells):
     cover |= cells; matches.append(cells)
 return cover,matches
